const productSlugTaken = `-- name: ProductSlugTaken :one
SELECT (EXISTS (
    SELECT 1 FROM products pr WHERE pr.workspace_id = $1 AND pr.id <> $2 AND pr.deleted_at IS NULL AND (pr.slug = $3 OR pr.live_slug = $3)
) OR EXISTS (
    SELECT 1 FROM product_redirects rd WHERE rd.workspace_id = $1 AND rd.slug = $3 AND rd.product_id <> $2
))::boolean AS taken
`

type ProductSlugTakenParams struct {
	WorkspaceID uuid.UUID `json:"workspaceId"`
	ID          uuid.UUID `json:"id"`
	Slug        string    `json:"slug"`
}

func (q *Queries) ProductSlugTaken(ctx context.Context, arg ProductSlugTakenParams) (bool, error) {
	row := q.db.QueryRow(ctx, productSlugTaken, arg.WorkspaceID, arg.ID, arg.Slug)
	var taken bool
	err := row.Scan(&taken)
	return taken, err
}

